mapper.select:
SELECT FROM expense_payers WHERE expense_id IN
#{expenseId,javaType=java.util.UUID,jdbcType=OTHER}
ORDER BY expense_id, position, id

mapper.update:
UPDATE expense_payers u
SET amount = u.amount + g.amount
FROM expense_payers g
WHERE g.guest_member_id = #{guestMemberId,javaType=java.util.UUID,jdbcType=OTHER}
  AND u.expense_id = g.expense_id
  AND u.user_id = #{userId,javaType=java.util.UUID,jdbcType=OTHER}

UPDATE expense_payers
SET user_id = #{userId,javaType=java.util.UUID,jdbcType=OTHER}, guest_member_id = NULL
WHERE guest_member_id = #{guestMemberId,javaType=java.util.UUID,jdbcType=OTHER}
